    // According to problem, 1 <= k < n, so k-1 is valid and not the last element.
    let remove_idx = k - 1;
    let n = list.len();

    // Create a new vector with capacity n-1 for efficiency.
    let mut new_list = Vec::with_capacity(n - 1);

